#!/usr/bin/env python3
"""Bounded loopback downloads for installed-app UI checks; serves generated bytes only."""
import argparse
import hashlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
from pathlib import Path
import socket
import threading
import time
from urllib.parse import urlsplit
import uuid


CHUNK = b"YNX generated download acceptance\n".ljust(16384, b".")
TOTAL = len(CHUNK) * 256
SUCCESS = CHUNK * 4
PAGE = b'''<!doctype html><meta charset="utf-8"><title>YNX Downloads QA</title>
<h1>Installed browser download checks</h1>
<p>Generated test bytes on loopback. This page does not test HTTPS or privacy routing.</p>
<ul><li><a href="/slow">Slow download: save, view progress, then cancel</a></li>
<li><a href="/broken">Broken download: expect failure, no completion</a></li>
<li><a href="/success">Small successful download</a></li></ul>'''


class Fixture(ThreadingHTTPServer):
    daemon_threads = True
    block_on_close = False

    def __init__(self, output, lifetime):
        self.output = output
        self.expires = time.monotonic() + lifetime
        self.stopped = threading.Event()
        self.lock = threading.Lock()
        self.requests = 0
        super().__init__(("127.0.0.1", 0), Handler)

    def record(self, **fields):
        with self.lock:
            with (self.output / "events.jsonl").open("a") as stream:
                stream.write(json.dumps(dict(at=time.time(), **fields), sort_keys=True) + "\n")


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        route = urlsplit(self.path).path
        if route not in ("/", "/slow", "/broken", "/success"):
            self.send_error(404)
            return
        with self.server.lock:
            self.server.requests += 1
            allowed = self.server.requests <= 32
        if not allowed or time.monotonic() >= self.server.expires:
            self.send_error(503)
            return
        request_id = str(uuid.uuid4())
        written = 0
        outcome = "not_sent"
        self.connection.settimeout(2)
        self.server.record(event="request", requestID=request_id, route=route)
        try:
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8" if route == "/" else "application/octet-stream")
            size = len(PAGE) if route == "/" else len(SUCCESS) if route == "/success" else TOTAL
            self.send_header("Content-Length", str(size))
            self.send_header("Cache-Control", "no-store")
            self.send_header("Connection", "close")
            if route != "/":
                self.send_header("Content-Disposition", 'attachment; filename="ynx-qa-' + route[1:] + '.bin"')
            self.end_headers()
            if route in ("/", "/success"):
                body = PAGE if route == "/" else SUCCESS
                self.wfile.write(body)
                self.wfile.flush()
                written = len(body)
                outcome = "complete"
            else:
                for index in range(256):
                    if self.server.stopped.is_set() or time.monotonic() >= self.server.expires:
                        outcome = "fixture_expired"
                        break
                    self.wfile.write(CHUNK)
                    self.wfile.flush()
                    written += len(CHUNK)
                    if route == "/broken" and index == 3:
                        outcome = "controlled_truncation"
                        self.connection.shutdown(socket.SHUT_RDWR)
                        break
                    # Enough time for the real Save sheet, Downloads view and Cancel.
                    if self.server.stopped.wait(0.25):
                        outcome = "fixture_stopped"
                        break
                else:
                    outcome = "complete"
        except (BrokenPipeError, ConnectionResetError, TimeoutError, OSError):
            outcome = "peer_closed_or_socket_error"
        finally:
            self.close_connection = True
            self.server.record(event="response_end", requestID=request_id, route=route,
                               bytesWritten=written, outcome=outcome)

    def log_message(self, *_):
        pass


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--lifetime", type=int, default=600)
    args = parser.parse_args()
    if not 15 <= args.lifetime <= 900:
        parser.error("lifetime must be between 15 and 900 seconds")
    args.output.mkdir(parents=True, exist_ok=False)
    server = Fixture(args.output, args.lifetime)
    receipt = dict(baseURL="http://127.0.0.1:" + str(server.server_port),
                   expiresAt=time.time() + args.lifetime, PID=__import__("os").getpid(),
                   successBytes=len(SUCCESS), successSHA256=hashlib.sha256(SUCCESS).hexdigest(),
                   advertisedSlowBytes=TOTAL, brokenActualBytes=len(CHUNK)*4,
                   arbitraryFilesystemServed=False, publiclyExposed=False,
                   installedBrowserAcceptance="NOT_RUN", privacyAcceptance="NOT_RUN")
    (args.output / "fixture.json").write_text(json.dumps(receipt, indent=2) + "\n")
    timer = threading.Timer(args.lifetime, server.shutdown)
    timer.daemon = True
    timer.start()
    try:
        server.serve_forever(poll_interval=0.1)
    finally:
        server.stopped.set()
        timer.cancel()
        server.server_close()
        server.record(event="fixture_closed")


if __name__ == "__main__":
    main()
